class Solution {
    public int removeDuplicates(int[] nums) {
        int write = 0;

        for (int value : nums) {
            if (write == 0 || nums[write - 1] != value) {
                nums[write] = value;
                write++;
            }
        }

        return write;
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {
        int write = 0;
        int read = 0;

        while (read < nums.length) {
            int value = nums[read];
            nums[write] = value;
            write++;

            while (read < nums.length && nums[read] == value) {
                read++;
            }
        }

        return write;
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {
        int write = 0;
        int read = 0;

        while (read < nums.length) {
            int value = nums[read];
            nums[write] = value;
            write++;
            read = upperBound(nums, read + 1, nums.length, value);
        }

        return write;
    }

    private int upperBound(int[] nums, int left, int right, int value) {
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] <= value) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {
        int length = nums.length;
        int i = 1;

        while (i < length) {
            if (nums[i] == nums[i - 1]) {
                for (int j = i; j < length - 1; j++) {
                    nums[j] = nums[j + 1];
                }
                length--;
            } else {
                i++;
            }
        }

        return length;
    }
}
